function tr(key){return T[locale][key]||key}
function localNumber(value){return locale==="fa"?faNum(value):enNum(value)}
function clean(text){return String(text||"")
  .replace(/[كيى]/g,char=>({"ك":"ک","ي":"ی","ى":"ی"}[char]))
  .replace(/\u200c{2,}/g,"‌")
  .replace(/ستون\s*([A-Z])/g,"ستون $1")
  .replace(/متوسط\s*(?=[۰-۹\d])/g,"متوسط ")
  .replace(/پایین\s*(?=[۰-۹\d])/g,"پایین ")
  .replace(/نسبتا(?!ً)/g,"نسبتاً")
  .replace(/می\s+شود/g,"می‌شود")
  .replace(/به\s+صورت/g,"به‌صورت")
  .replace(/قابل\s+دسترسی/g,"قابل‌دسترسی")
  .replace(/قابل\s+تشخیص/g,"قابل‌تشخیص")
  .replace(/قابل\s+درک/g,"قابل‌درک")
  .replace(/\s{2,}/g," ")
  .replace(/\s+([،؛:،.])/g,"$1")
  .replace(/\s*–\s*/g," — ")
  .trim()}
