function itemTitle(item){
  if(item.titleFa)return clean(item.titleFa);
  if(ITEM_TITLES[item.id])return ITEM_TITLES[item.id];
  let plain=clean(item.textFa).replace(/^گام\s*[۰-۹\d]+\.?\s*/,"");
  // The source document usually starts each item with its intended noun-phrase
  // heading, followed by the observation procedure.  Keep only that heading.
  const actionStart=/\s+(?=(?:روی صندلی|خودرو را|موتور را|کولر را|صندلی را|در را|کاپوت را|فرمان را|آینه‌ها را|سطح را|دستانت را|پدال |با سرعت|در سرعت|پس از|هنگام|حین|بدون|از روی|در محیط|در جاده|در هوای|از فاصله|از زاویه|در حالت|بنشین|وارد شو|حرکت کن|حرکت کنید|بررسی کن|بررسی کنید|مشاهده کن|مشاهده کنید|باز کن|باز کنید|روشن کن|روشن کنید|لمس کن|لمس کنید|بران|برو|بده|قرار بده|قرار گیرد|تنظیم کن|تنظیم کنید|نگاه کن|نگاه کنید|امتحان کن|امتحان کنید|تست کن|تست کنید|ارزیابی کن|ارزیابی کنید|بازدید کن|بازدید کنید|بگیر|بگیرید|ببند|ببندید|بچرخان|بچرخانید|فشار بده|فشار دهید|بکش|بکشید|بشمار|بشمارید|لحاظ کن|لحاظ کنید|شبیه‌سازی کن|شبیه‌سازی کنید))/;
  const match=plain.match(actionStart);
  if(match)plain=plain.slice(0,match.index);
  else {const colon=plain.search(/[:؛]/);if(colon>4&&colon<110)plain=plain.slice(0,colon)}
  plain=plain.replace(/\s+(?:را|و|در|از|با)$/," ").trim();
  return plain.length>3?plain:tr("guidance");
}
