  const rawConfiguredWeights=window.ASSESSMENT_CRITERIA.map(main=>{const w=Number(state.weights[main.id]??(1/criteriaCount));return Number.isFinite(w)&&w>=0?w:0});
  const rawWeightTotal=rawConfiguredWeights.reduce((sum,weight)=>sum+weight,0);
  const configuredWeights=rawWeightTotal>0?rawConfiguredWeights.map(weight=>weight/rawWeightTotal):window.ASSESSMENT_CRITERIA.map(()=>1/criteriaCount);
  const configuredWeightTotal=configuredWeights.reduce((sum,weight)=>sum+weight,0);
  let scored=0;
  const rows=window.ASSESSMENT_CRITERIA.map((main,index)=>{const vals=valuesForMain(main);const counts=mainCounts(main);scored+=vals.length;const avg=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:NaN;const avg100=Number.isFinite(avg)?avg*10:NaN;const weight=configuredWeights[index];const weightedContribution=Number.isFinite(avg100)&&Number.isFinite(weight)?avg100*weight:NaN;const completion=counts.total?counts.answered/counts.total*100:0;return {main,avg,avg100,weight,ws:weightedContribution,final100:weightedContribution,completion,answered:counts.answered,total:counts.total}});
  const completedRows=rows.filter(row=>Number.isFinite(row.final100)&&Number.isFinite(row.weight));
  const completedWeight=completedRows.reduce((sum,row)=>sum+row.weight,0);
  const final100=completedWeight>0?completedRows.reduce((sum,row)=>sum+row.final100,0)/completedWeight:NaN;
  const final=Number.isFinite(final100)?final100/10:NaN,totalItems=window.ASSESSMENT_CRITERIA.flatMap(m=>m.subgroups.flatMap(s=>s.items)).length;
  const percent=totalItems?Math.round(scored/totalItems*100):0;$("#finalScore").textContent=fmt(Number.isFinite(final)?final*10:NaN);$("#completionText").textContent=locale==="fa"?`${localNumber(scored)} از ${localNumber(totalItems)}`:`${localNumber(scored)} of ${localNumber(totalItems)}`;$("#progressBar").style.width=`${percent}%`;$("#evaluatorCompletionPercent").textContent=`${localNumber(percent)}٪`;$("#evaluatorCompletionText").textContent=locale==="fa"?`${localNumber(scored)} از ${localNumber(totalItems)} پاسخ`:`${localNumber(scored)} of ${localNumber(totalItems)} answered`;$("#evaluatorProgressBar").style.width=`${percent}%`;
  const [verdict,hint,color]=decision(final);$("#verdict").textContent=verdict;$("#verdictHint").textContent=hint;$("#verdict").style.color=`var(--${color||'text'})`;
  const accents=['#2463a5','#b54d66','#128778','#d58a24','#7454b8','#d9673a','#3e8c47','#ad5f99','#2c7d9a','#96733c','#5475b5','#b85c48','#4b9a91','#8f5c6b','#527e50'];
  const h=locale==="fa"?["ردیف","آیکون","شاخص","میانگین از ۱۰","وزن","سهم در امتیاز کل","نرخ تکمیل"]:["No.","Icon","Criterion","Average / 10","Weight","Contribution / 100","Completion"];
  const notRated=locale==="fa"?"ارزیابی نشده":"Not assessed";
  $("#summaryBody").innerHTML=`<div class="integratedSummaryHead">${h.map(x=>`<span>${x}</span>`).join("")}</div>${rows.map((r,index)=>{const heat=completionHeat(r.completion);const pct=Math.round(r.completion);return `<article class="integratedSummaryRow" style="--row-accent:${accents[index]};--completion-color:${heat.solid};--completion-soft:${heat.soft};--completion-percent:${pct}%"><span class="integratedRowNumber">${localNumber(index+1)}</span><span class="integratedIcon">${criterionIconForMain(r.main)}</span><strong>${title(r.main.titleFa,"main",r.main.id)}</strong><span class="integratedScore">${Number.isFinite(r.avg)?fmt(r.avg):notRated}</span><span class="integratedWeight">${localNumber(Number(r.weight).toFixed(3))}</span><span class="integratedFinal">${Number.isFinite(r.final100)?fmt(r.final100):notRated}</span><span class="integratedCompletion"><span class="completionVisual"><b>${localNumber(pct)}٪</b><span class="completionMeter" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><i aria-hidden="true"></i></span></span><small>${locale==="fa"?`${localNumber(r.answered)} از ${localNumber(r.total)}`:`${localNumber(r.answered)} of ${localNumber(r.total)}`}</small></span></article>`}).join("")}`;
  $("#summaryFinal").textContent=fmt(Number.isFinite(final)?final*10:NaN);
  rows.forEach(r=>{const out=$("#tab-score-"+r.main.id);if(out)out.textContent=fmt(r.avg);const progress=$("#tab-progress-"+r.main.id);if(progress){const count=mainCounts(r.main);progress.textContent=`${localNumber(count.answered)} ${locale==="fa"?"از":"of"} ${localNumber(count.total)}`;progress.classList.toggle("complete",count.answered===count.total)}});renderChart(rows);renderQualityChart();updateMainScore();if(window.managerRefresh)window.managerRefresh(rows,final,percent);
