function renderMetadata(){document.querySelectorAll("[data-meta]").forEach(el=>{const key=el.dataset.meta,value=state.metadata[key]||"";el.value=key==="date"?formatAssessmentDate(state.metadata.date):(el.dataset.localizedNumber&&locale==="fa"?faNum(value):value);if(el.dataset.bound)return;el.dataset.bound="1";if(key==="date"){el.addEventListener("click",()=>openJalaliCalendar(el));el.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();openJalaliCalendar(el)}})}else el.addEventListener("input",e=>{if(e.target.dataset.localizedNumber&&locale==="fa")e.target.value=faNum(e.target.value);state.metadata[e.target.dataset.meta]=e.target.value;persist()})})}
function englishFileToken(value,fallback="vehicle"){
  const ascii=String(value||"").normalize("NFKD").replace(/[^\x00-\x7F]/g,"").replace(/[^A-Za-z0-9._-]+/g,"_").replace(/^_+|_+$/g,"");
  return ascii||fallback;
}
window.englishFileToken=englishFileToken;
function download(){const blob=new Blob([JSON.stringify({version:2,savedAt:new Date().toISOString(),state},null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`vehicle_assessment_${englishFileToken(state.metadata.model,"vehicle")}.json`;a.click();URL.revokeObjectURL(a.href)}
function esc(value){return String(value??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")}
function persianCriterionName(main){return clean(main?.titleFa||"").replace(/\([^)]*[A-Za-z][^)]*\)/g,"").replace(/[A-Za-z][A-Za-z0-9&/\-–—., ]*/g,"").replace(/[\s\/\-–—]+$/g,"").replace(/\s+/g," ").trim()}
function excelImagePayload(photo){
  if(!photo||!photo.data)return null;
  const data=String(photo.data||"");
  const m=data.match(/^data:image\/([^;]+);base64,(.*)$/i);
  const mime=String(photo.type||m?.[1]||"jpeg").toLowerCase();
  const extension=mime.includes("png")?"png":mime.includes("gif")?"gif":"jpeg";
  const base64=m?m[2]:data.replace(/^data:[^,]+,/,"");
  return base64?{base64,extension}:null;
}
