  ws.views=[{rightToLeft:fa,showGridLines:false}];ws.properties.defaultRowHeight=20;
  ws.mergeCells("A1:H1");ws.getCell("A1").value=txt("چهار نمای خودرو","Four Vehicle Views");
  ws.getCell("A1").font={bold:true,size:17,color:{argb:"FFFFFFFF"}};ws.getCell("A1").fill={type:"pattern",pattern:"solid",fgColor:{argb:"FF163B69"}};ws.getCell("A1").alignment={horizontal:"center",vertical:"middle"};ws.getRow(1).height=32;
